/// The advertised tool list (`tools/list`).
pub fn list() -> Vec<Value> {
    let mut tools = vec![session_definition(), storage_definition()];
    tools.extend(constitution::definitions());
    tools.extend(amendments::definitions());
    tools.extend(executive::definitions());
    tools.extend(conformance::definitions());
    tools.extend(controls::definitions());
    tools.extend(waivers::definitions());
    tools.extend(knowledge::definitions());
    tools.extend(lifecycle::definitions());
    tools.extend(design::definitions());
    tools.extend(design_materialization::definitions());
    tools.extend(evidence::definitions());
    tools.extend(fleet::definitions());
    tools.into_iter().map(apply_session_contract).collect()
}

/// The argument names a tool declares, from the schema it already advertises.
///
/// Returns `None` for a name no tool declares, so dispatch keeps reporting the
/// unknown *tool* rather than complaining about its arguments.
fn declared_arguments(name: &str) -> Option<Vec<String>> {
    list().into_iter().find_map(|tool| {
        if tool.get("name").and_then(Value::as_str) != Some(name) {
            return None;
        }
        Some(
            tool.get("inputSchema")
                .and_then(|schema| schema.get("properties"))
                .and_then(Value::as_object)
                .map(|properties| properties.keys().cloned().collect())
                .unwrap_or_default(),
        )
    })
}

/// Keys that belong to the call envelope rather than to any tool's contract.
///
/// `agent`, `resolved_agent`, `resolved_name` and `resolved_context` are
/// injected by the server (`bind_session`); tolerating them keeps validation
/// idempotent, because binding already-bound params must not report the
/// server's own additions as the caller's mistake.
///
/// `session_id` is the mirror case, supplied by the client. Every MCP client
/// here adds it to *every* call — the VS Code extension does so in one place
/// (`mcpClient.callTool`) rather than per tool — while `apply_session_contract`
/// only declares it on tools that `requires_session`. Reading it as an argument
/// therefore rejects every call to a tool that does not need a session
/// (`board`, `design_board`, `graph_stats`, …), which is how this first showed
/// up: the extension reached `disconnected` instead of `ready_empty` because
/// its whole readiness path is such tools. Who supplies an envelope key is not
/// what makes it one.
const ENVELOPE_ARGUMENTS: [&str; 5] = [
    "agent",
    "resolved_agent",
    "resolved_name",
    "resolved_context",
    "session_id",
];

/// Refuse an argument no tool declares.
///
/// A misspelt optional argument used to be dropped in silence and the default
/// applied: `lease_seconds` instead of `lease_secs` produced a 300-second lease
/// that lapsed mid-work, and the only symptom was a claim that had quietly
/// expired. Nothing pointed at the typo. A caller that names something the tool
/// does not have is wrong about the contract, and the cheapest moment to say so
/// is immediately.
///
/// Only top-level names are checked, and only against tools that declare a
/// schema — this validates the call, not the shape of every nested payload.
pub fn validate_arguments(name: &str, args: &Value) -> Result<(), String> {
    let Some(declared) = declared_arguments(name) else {
        return Ok(());
    };
    let Some(supplied) = args.as_object() else {
        return Ok(());
    };
    let mut unknown: Vec<&str> = supplied
        .keys()
        .map(String::as_str)
        .filter(|key| !ENVELOPE_ARGUMENTS.contains(key))
        .filter(|key| !declared.iter().any(|allowed| allowed == key))
        .collect();
    if unknown.is_empty() {
        return Ok(());
    }
    unknown.sort_unstable();
    let mut accepted = declared;
    accepted.sort();
    let accepted = if accepted.is_empty() {
        "none".to_string()
    } else {
        accepted.join(", ")
    };
    Err(format!(
        "unknown argument(s) for {name}: {}. Accepted: {accepted}. \
         A misspelt argument is dropped, not defaulted deliberately \u{2014} \
         check the spelling rather than the value.",
        unknown.join(", ")
    ))
}

pub fn bind_session(params: &Value, sessions: &SessionRegistry) -> Result<Value, String> {
    let name = params.get("name").and_then(Value::as_str).unwrap_or("");
    let mut bound = params.clone();
    let args = bound
        .get_mut("arguments")
        .and_then(Value::as_object_mut)
        .ok_or_else(|| "tool arguments must be an object".to_string())?;
    // Checked before anything is injected, so the caller is judged on exactly
    // what the caller sent.
    validate_arguments(name, &Value::Object(args.clone()))?;
    if name == "open_session" {
        let token = args
            .get("session_id")
            .and_then(Value::as_str)
            .ok_or_else(|| "missing required string arg: session_id".to_string())?;
        let declared = SessionContext::from_arguments(&Value::Object(args.clone()))?;
        let identity = sessions.open_session(token, declared)?;
        args.insert("resolved_agent".to_string(), json!(identity.agent_id));
        args.insert("resolved_name".to_string(), json!(identity.name));
        if let Some(context) = identity.context.declared_json() {
            args.insert("resolved_context".to_string(), context);
        }
        return Ok(bound);
    }
    if requires_session(name) {
        let token = args
            .get("session_id")
            .and_then(Value::as_str)
            .ok_or_else(|| "missing required string arg: session_id".to_string())?;
        let identity = sessions.resolve(token)?;
        args.insert("agent".to_string(), json!(identity.agent_id));
        args.insert("resolved_name".to_string(), json!(identity.name));
        if let Some(evidence) = args.get_mut("evidence").and_then(Value::as_object_mut) {
            evidence.insert("agent_id".to_string(), json!(identity.agent_id));
        }
    }
    Ok(bound)
}

/// Dispatch a `tools/call`. Returns the MCP `content` object or an error string.
#[cfg(test)]
pub fn call(engine: &Lodestar, params: &Value) -> Result<Value, String> {
    call_with_storage(engine, params, None)
}

pub fn call_with_storage(
    engine: &Lodestar,
    params: &Value,
    storage: Option<&StorageStatus>,
) -> Result<Value, String> {
    let name = params.get("name").and_then(Value::as_str).unwrap_or("");
    let args = params.get("arguments").cloned().unwrap_or(Value::Null);

    if name == "open_session" {
        let agent_id = req_str(&args, "resolved_agent")?;
        // Persist here rather than in bind_session: the fleet spans processes,
        // so a view backed by the in-memory registry would report only the
        // sessions of whichever server answered while looking like the whole
        // fleet (ADR-0044). bind_session has no engine; this is the first point
        // that does.
        //
        // Only a call that actually declares something writes. Declaring
        // nothing is not declaring emptiness: a re-registration for identity
        // alone — which every publish does — would otherwise erase the branch
        // and head this session had already reported, and `fleet_view` would go
        // blind precisely when the fleet is busiest. Within a real declaration
        // the store still replaces wholesale, because an omitted field there is
        // the client saying that field is no longer known.
        let declared = SessionContext::from_arguments(&args)?;
        if declared.is_declared() {
            engine
                .declare_session_context(agent_id, &declared)
                .map_err(|e| e.to_string())?;
        }
        let mut body = json!({ "agent_id": agent_id });
        if let Some(context) = args.get("resolved_context") {
            body["context"] = context.clone();
        }
        return ok(&body);
    }
    if name == "storage_status" {
        return ok(storage.ok_or("storage status is unavailable")?);
    }

    // Proof of life before the call runs, so a slow tool cannot lapse the very
    // lease its caller is demonstrating (ADR-0052).
    touch_named_task(engine, name, &args);

    if let Some(result) = constitution::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = amendments::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = executive::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = conformance::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = controls::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = waivers::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = knowledge::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = lifecycle::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = design::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = design_materialization::dispatch(engine, name, &args) {
        return result;
    }

    if let Some(result) = evidence::dispatch(engine, name, &args) {
        return result;
    }
    if let Some(result) = fleet::dispatch(engine, name, &args) {
        return result;
    }

    Err(format!("unknown tool: {name}"))
}

/// Calls that prove their caller is still working on the task they name
/// (ADR-0052). Reading a task's scope, asking or answering a question about it,
/// reviewing its conformance history, or checking its evidence are all things
/// only an agent mid-task does.
///
/// `claim_task` and `renew_lease` are absent deliberately: they set the lease
/// themselves, and a heartbeat afterwards would silently widen what the caller
/// asked for. `complete_task` and `release_task` are absent because the claim is
/// ending, not continuing.
const HEARTBEAT_TOOLS: &[&str] = &[
    "task_scope",
    "ask_question",
    "answer",
    "conformance_history",
    "check_conformance",
];

// `advise` is deliberately absent, answering the question ADR-0052 left open.
//
// ADR-0052 listed it as proof of life, then said in the same breath that
// "`advise` should be excluded, or ADR-0029 amended — this decision does not get
// to quietly redefine another one." ADR-0029 still documents `advise` as
// evidence-free and state-free: it "records no conformance verdict, and changes
// no task state". A lease renewal *is* task state, so including it here would
// have made one ADR quietly contradict another, which is the specific outcome
// ADR-0052 asked us to avoid.
//
// Excluding it costs almost nothing: an agent calling `advise` before it edits
// is about to call something task-bearing anyway. If the fleet decides `advise`
// should renew, that is an amendment to ADR-0029 with its own reasoning — not a
// line added back to this array.

/// Seconds a heartbeat extends a lease to. Deliberately the same as the default
/// claim, so activity keeps a claim alive exactly as long as claiming it would —
/// the short default is what frees a vanished agent's work quickly, and
/// renewal-on-activity keeps that property instead of trading it away by raising
/// the default.
const HEARTBEAT_LEASE_SECS: i64 = 300;

/// Renew the lease on the task a call names, if the caller owns it (ADR-0052).
///
/// Failure is ignored on purpose: a non-owner, a lapsed lease, or a call naming
/// no task all renew nothing, and none of them is an error in the call that was
/// actually made. A lapse still requires a deliberate re-claim, so this cannot
/// resurrect a claim someone else has taken.
fn touch_named_task(engine: &Lodestar, name: &str, args: &Value) {
    if !HEARTBEAT_TOOLS.contains(&name) {
        return;
    }
    let Some(task_id) = args.get("task_id").and_then(Value::as_str) else {
        return;
    };
    let agent = args
        .get("resolved_agent")
        .or_else(|| args.get("agent"))
        .and_then(Value::as_str)
        .unwrap_or_default();
    if agent.is_empty() {
        return;
    }
    let _ = engine.touch_lease(task_id, agent, HEARTBEAT_LEASE_SECS);
}

fn session_definition() -> Value {
    json!({
        "name": "open_session",
        "description": "Register one client-minted 128-bit session id and return its stable cross-plane agent identity. Optionally declare where this session is working (branch, head_sha, base, dirty); the server records what you declare and never inspects Git itself. Reuse the same session_id on every identity-bearing tool call and after server restarts.",
        "inputSchema": session_input_schema()
    })
}

fn storage_definition() -> Value {
    json!({
        "name": "storage_status",
        "description": "Report this plane's resolved repository id, database path, storage origin, legacy migration source, and whether migration ran. Read-only; uses the startup snapshot without re-reading Git or SQLite.",
        "inputSchema": { "type": "object", "properties": {} }
    })
}

fn requires_session(name: &str) -> bool {
    matches!(
        name,
        "register_design"
            | "review_pack_clause"
            | "propose_constitution"
            | "activate_constitution"
            | "claim_task"
            | "renew_lease"
            | "complete_task"
            | "release_task"
            | "recover_claim"
            | "ask_question"
            | "pending_questions"
            | "pause_task"
            | "resume_task"
            | "check_conformance"
            | "accept_ratchet_baseline"
            | "retire_control"
            | "grant_waiver"
            | "revoke_waiver"
            | "propose_amendment"
            | "amend_constitution"
    )
}

fn apply_session_contract(mut tool: Value) -> Value {
    let name = tool.get("name").and_then(Value::as_str).unwrap_or("");
    if !requires_session(name) {
        return tool;
    }
    if let Some(properties) = tool
        .get_mut("inputSchema")
        .and_then(|schema| schema.get_mut("properties"))
        .and_then(Value::as_object_mut)
    {
        properties.remove("agent");
        properties.insert(
            "session_id".to_string(),
            json!({
                "type": "string",
                "pattern": "^[0-9a-f]{32}$",
                "description": "Session id previously registered with open_session."
            }),
        );
    }
    if let Some(required) = tool
        .get_mut("inputSchema")
        .and_then(|schema| schema.get_mut("required"))
        .and_then(Value::as_array_mut)
    {
        required.retain(|value| value != "agent");
        if !required.iter().any(|value| value == "session_id") {
            required.push(json!("session_id"));
        }
    } else if let Some(schema) = tool.get_mut("inputSchema").and_then(Value::as_object_mut) {
        schema.insert("required".to_string(), json!(["session_id"]));
    }
    tool
}

// ---- helpers ---------------------------------------------------------------

pub(super) fn req_str<'a>(args: &'a Value, key: &str) -> Result<&'a str, String> {
    args.get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("missing required string arg: {key}"))
}

pub(super) fn opt_str(args: &Value, key: &str) -> Option<String> {
    args.get(key)
        .and_then(Value::as_str)
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
}

pub(super) fn optional_string_arg(args: &Value, key: &str) -> Result<Option<String>, String> {
    match args.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(value)) if !value.trim().is_empty() => Ok(Some(value.clone())),
        Some(Value::String(_)) => Err(format!("argument {key} must not be empty")),
        Some(_) => Err(format!("argument {key} must be a string")),
    }
}

pub(super) fn i64_arg(args: &Value, key: &str, default: i64) -> i64 {
    args.get(key).and_then(Value::as_i64).unwrap_or(default)
}

pub(super) fn bool_arg(args: &Value, key: &str, default: bool) -> bool {
    args.get(key).and_then(Value::as_bool).unwrap_or(default)
}

pub(super) fn f64_arg(args: &Value, key: &str, default: f64) -> f64 {
    args.get(key).and_then(Value::as_f64).unwrap_or(default)
}

pub(super) fn str_array(args: &Value, key: &str) -> Vec<String> {
    args.get(key)
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect()
        })
        .unwrap_or_default()
}

pub(super) fn ok<T: Serialize>(value: &T) -> Result<Value, String> {
    let body = serde_json::to_string_pretty(value).map_err(|e| e.to_string())?;
    text(body)
}

/// A tool result that renders as Markdown in chat while keeping the structured
/// JSON in `structuredContent` for programmatic consumers (the extension client
/// and agents). VS Code renders `content`; machine consumers read
/// `structuredContent`, so display can be rich without breaking parsers.
pub(super) fn rendered<T: Serialize>(
    markdown: impl Into<String>,
    value: &T,
) -> Result<Value, String> {
    let structured = serde_json::to_value(value).map_err(|e| e.to_string())?;
    Ok(json!({
        "content": [{ "type": "text", "text": markdown.into() }],
        "structuredContent": structured,
    }))
}

pub(super) fn text(body: String) -> Result<Value, String> {
    Ok(json!({ "content": [{ "type": "text", "text": body }] }))
}

#[cfg(test)]
mod tests {
    use super::*;
    use mindleak_storage::DatabaseOrigin;
    use std::path::PathBuf;

    /// `advise` must not renew a lease, because ADR-0029 says it changes no
    /// task state.
    ///
    /// ADR-0052 raised this and deliberately did not settle it: "`advise` should
    /// be excluded, or ADR-0029 amended — this decision does not get to quietly
    /// redefine another one." The first implementation included it, which made
    /// the two ADRs contradict each other in code while both still read as
    /// authoritative. This test is the guard: re-adding `advise` to
    /// `HEARTBEAT_TOOLS` without first amending ADR-0029 fails here.
    #[test]
    fn advise_is_not_a_heartbeat_while_adr_0029_calls_it_state_free() {
        assert!(
            !HEARTBEAT_TOOLS.contains(&"advise"),
            "advise renews a lease, which is task state; ADR-0029 documents it \
             as state-free. Amend ADR-0029 before adding it back."
        );
        // The tools that *are* heartbeats stay heartbeats: this must not be
        // read as "renewal-on-activity was reverted".
        for expected in ["task_scope", "conformance_history", "check_conformance"] {
            assert!(
                HEARTBEAT_TOOLS.contains(&expected),
                "{expected} is proof the owner is still working (ADR-0052)"
            );
        }
    }

    /// Every argument a handler requires is either declared or injected.
    ///
    /// Two ways an argument reaches a handler: the caller sends it, having read
    /// it in the schema, or `bind_session` injects it after resolving the
    /// session. `agent` is the second kind — `apply_session_contract` strips it
    /// from every session-requiring tool and puts `session_id` in its place, so
    /// attribution on the verbs that change law, grant waivers and accept
    /// ratchet baselines is *resolved*, never asserted by the caller. A tool
    /// declaring `agent` would let a caller name itself anything it liked.
    ///
    /// That leaves a gap a reader falls into: a handler saying
    /// `req_str(args, "agent")` beside a schema that never mentions `agent`
    /// reads exactly like the `lease_secs` incident above, and the failure mode
    /// if it ever *were* one is identical — `missing required string arg`
    /// naming a field the tool does not advertise. This pins the real rule so
    /// the two cases stay distinguishable: required, and neither declared nor
    /// injected, is a broken contract.
    ///
    /// Read from the source rather than exercised, because a handler's
    /// requirements are only observable by calling it with each argument
    /// missing — which for these verbs means mutating live policy to find out.
    #[test]
    fn a_required_argument_is_either_declared_or_session_injected() {
        /// Inserted by `bind_session` once the session resolves.
        const INJECTED: [&str; 4] = [
            "agent",
            "resolved_agent",
            "resolved_name",
            "resolved_context",
        ];

        const SOURCES: [(&str, &str); 6] = [
            ("amendments", include_str!("amendments.rs")),
            ("constitution", include_str!("constitution.rs")),
            ("controls", include_str!("controls.rs")),
            ("waivers", include_str!("waivers.rs")),
            ("executive", include_str!("executive.rs")),
            ("design", include_str!("design.rs")),
        ];

        let mut unreachable: Vec<String> = Vec::new();
        let mut inspected = 0usize;

        for (module, source) in SOURCES {
            for (offset, _) in source.match_indices("\nfn ") {
                let after = &source[offset + 4..];
                let Some(paren) = after.find('(') else {
                    continue;
                };
                let name = after[..paren].trim();
                let Some(declared) = declared_arguments(name) else {
                    continue;
                };
                let injected = requires_session(name);

                // The handler body ends where the next top-level fn begins.
                let body_end = after.find("\nfn ").unwrap_or(after.len());
                let body = &after[..body_end];

                for (at, _) in body.match_indices("req_str(args, \"") {
                    let rest = &body[at + "req_str(args, \"".len()..];
                    let Some(end) = rest.find('"') else { continue };
                    let argument = &rest[..end];
                    inspected += 1;

                    if declared.iter().any(|d| d == argument) {
                        continue;
                    }
                    if injected && INJECTED.contains(&argument) {
                        continue;
                    }
                    unreachable.push(format!("{module}::{name} requires `{argument}`"));
                }
            }
        }

        // A source scan degrades silently: rename a handler, change how an
        // argument is read, and the loop inspects nothing while still passing.
        // The floor makes that show up as a failure instead of a green tick
        // over an empty set.
        assert!(
            inspected >= 25,
            "the scan found only {inspected} required arguments, so it is no \
             longer reading the handlers it claims to guard"
        );

        assert!(
            unreachable.is_empty(),
            "no caller can satisfy these — undeclared, and not injected by the \
             session contract:\n  {}",
            unreachable.join("\n  ")
        );
    }

    /// The incident: `lease_seconds` was passed where the tool declares
    /// `lease_secs`. The key was dropped, the 300-second default applied, and
    /// the claim lapsed mid-work. Nothing named the typo, so the lease looked
    /// like a server bug for twenty minutes. A caller naming an argument the
    /// tool does not have is wrong about the contract, and silence is the
    /// expensive answer.
    #[test]
    fn an_unknown_argument_is_reported_instead_of_silently_dropped() {
        let error = validate_arguments(
            "claim_task",
            &json!({ "task_id": "task:1", "lease_seconds": 3600 }),
        )
        .expect_err("a misspelt argument is refused");

        assert!(
            error.contains("lease_seconds"),
            "names the offending key: {error}"
        );
        assert!(
            error.contains("lease_secs"),
            "names what was accepted: {error}"
        );
    }

    #[test]
    fn a_correctly_named_argument_still_passes() {
        validate_arguments(
            "claim_task",
            &json!({ "task_id": "task:1", "lease_secs": 3600 }),
        )
        .expect("declared arguments are accepted");
    }

    /// The server injects `agent` into arguments for session-bearing tools.
    /// Reporting its own addition as the caller's mistake would make binding
    /// non-idempotent and blame the wrong party.
    #[test]
    fn the_servers_own_injected_arguments_are_not_the_callers_mistake() {
        validate_arguments(
            "claim_task",
            &json!({ "task_id": "task:1", "agent": "session:v1:copilot:abc" }),
        )
        .expect("injected keys are tolerated");
    }

    /// An unknown tool must keep reporting the unknown *tool*; complaining
    /// about its arguments would bury the actual problem.
    #[test]
    fn an_unknown_tool_is_not_reported_as_an_argument_problem() {
        validate_arguments("no_such_tool", &json!({ "anything": 1 }))
            .expect("argument validation defers to tool dispatch");
    }

    /// Bug regression. Argument validation rejected `session_id` on every tool
    /// outside `requires_session`, because only those tools get it added to
    /// their schema by `apply_session_contract` — but the client adds it to
    /// every call, in one place, not per tool. The extension's whole readiness
    /// path is such tools, so it reported `disconnected` instead of
    /// `ready_empty` and the Extension Host smoke was the only thing that
    /// noticed. Validating the envelope as if it were a tool argument breaks
    /// every caller that speaks the protocol correctly.
    ///
    /// Asserted over the readiness tools by name: a whitelist entry is easy to
    /// drop in a refactor, and the unit that catches it must be the call the
    /// client actually makes.
    #[test]
    fn the_session_envelope_is_accepted_by_tools_that_never_declare_it() {
        for tool in ["board", "design_board"] {
            assert!(
                !requires_session(tool),
                "{tool} is the case worth testing only while it declares no session"
            );
            validate_arguments(
                tool,
                &json!({ "session_id": "0123456789abcdef0123456789abcdef" }),
            )
            .unwrap_or_else(|error| panic!("{tool} must accept the envelope: {error}"));
        }
        // ...and it stays acceptable alongside a real declared argument.
        validate_arguments(
            "board",
            &json!({ "include_terminal": false, "session_id": "0123456789abcdef0123456789abcdef" }),
        )
        .expect("the envelope does not invalidate declared arguments");
    }

    /// The envelope is tolerated; a genuine typo beside it is still caught.
    /// Widening the whitelist must not become a way to smuggle mistakes past
    /// the check this change exists to add.
    #[test]
    fn tolerating_the_envelope_does_not_excuse_a_misspelt_argument() {
        let error = validate_arguments(
            "claim_task",
            &json!({
                "task_id": "task:1",
                "lease_seconds": 3600,
                "session_id": "0123456789abcdef0123456789abcdef"
            }),
        )
        .expect_err("a misspelt argument is still refused");
        assert!(
            error.contains("lease_seconds"),
            "names the offending key: {error}"
        );
        // Only the blamed list matters here. `claim_task` does require a
        // session, so `session_id` legitimately appears in "Accepted:" —
        // asserting over the whole message would fail for the wrong reason.
        let blamed = error
            .split_once("Accepted:")
            .map(|(before, _)| before)
            .unwrap_or(&error);
        assert!(
            !blamed.contains("session_id"),
            "does not blame the envelope: {error}"
        );
    }

    // ADR-0035 decisions 1 and 6, on the Intent Plane. Both planes share one
    // registry and one input schema, so the risk is that only one of them is
    // actually wired; this proves the Lodestar side records and echoes what a
    // client declares, and stays silent when it declares nothing.
    #[test]
    fn open_session_records_declared_context_and_omits_it_when_undeclared() {
        let engine = Lodestar::open_in_memory().expect("in-memory engine");
        let sessions = SessionRegistry::new("copilot").unwrap();
        const TOKEN: &str = "00112233445566778899aabbccddeeff";
        let body = |arguments: Value| -> Value {
            let params = json!({ "name": "open_session", "arguments": arguments });
            let bound = bind_session(&params, &sessions).expect("session binds");
            let result = call(&engine, &bound).expect("open_session succeeds");
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap())
                .expect("body is JSON")
        };

        let undeclared = body(json!({ "session_id": TOKEN }));
        assert!(undeclared["agent_id"].is_string());
        assert!(undeclared.get("context").is_none());

        let declared = body(json!({
            "session_id": TOKEN,
            "branch": "fleet/typed-controls",
            "dirty": false,
        }));
        assert_eq!(declared["agent_id"], undeclared["agent_id"]);
        assert_eq!(declared["context"]["branch"], "fleet/typed-controls");
        assert_eq!(declared["context"]["dirty"], false);
        assert!(declared["context"].get("head_sha").is_none());
        assert_eq!(
            sessions.resolve(TOKEN).unwrap().context.branch.unwrap(),
            "fleet/typed-controls"
        );
    }

    // Regression (ADR-0044): the durable row survives a bare re-registration.
    //
    // `canonical-push` re-opens the session on every publish just to learn its
    // own agent id, declaring nothing. That used to overwrite the stored row
    // with an empty one, so `fleet_view` reported `branch: null` for agents that
    // had declared a branch minutes earlier — the fleet went blind at exactly
    // the moment it was busiest, and the tool that blinded it was the one added
    // to record where everyone was working.
    #[test]
    fn a_bare_re_registration_does_not_erase_the_durable_context() {
        let engine = Lodestar::open_in_memory().expect("in-memory engine");
        let sessions = SessionRegistry::new("copilot").unwrap();
        const TOKEN: &str = "aabbccddeeff00112233445566778899";
        let open = |arguments: Value| {
            let params = json!({ "name": "open_session", "arguments": arguments });
            let bound = bind_session(&params, &sessions).expect("session binds");
            call(&engine, &bound).expect("open_session succeeds");
        };

        open(json!({ "session_id": TOKEN, "branch": "fleet/claim-gate", "behind": 0 }));
        let agent_id = sessions.resolve(TOKEN).unwrap().agent_id;
        assert_eq!(
            engine.fleet_view().unwrap().sessions[0].context.branch,
            Some("fleet/claim-gate".to_string())
        );

        // The publish path: identity only, nothing declared.
        open(json!({ "session_id": TOKEN }));

        let view = engine.fleet_view().unwrap();
        let session = view
            .sessions
            .iter()
            .find(|session| session.agent_id == agent_id)
            .expect("the session is still in the view");
        assert_eq!(session.context.branch, Some("fleet/claim-gate".to_string()));
        assert_eq!(session.context.behind, Some(0));
    }

    /// Every tool the server will answer to is a tool it advertises.
    ///
    /// `active_knowledge` dispatched for months and appeared in no
    /// `definitions()` list, so the only way to discover that the repository's
    /// learned knowledge could be read at all was to read the Rust. From the
    /// tool surface the knowledge base looked write-only: record, promote,
    /// reconfirm, prune, and no way to see what was already known — which is
    /// exactly the state that makes an agent rediscover, expensively, what
    /// somebody already wrote down.
    ///
    /// This is the mirror of the undeclared-argument bug above. There the
    /// contract asked for something it never mentioned; here the server answers
    /// to something it never mentions. Both fail the same way: the code is
    /// right, the advertisement is wrong, and nothing breaks loudly enough to
    /// be found.
    #[test]
    fn every_tool_the_server_answers_to_is_advertised() {
        const SOURCES: [(&str, &str); 13] = [
            ("amendments", include_str!("amendments.rs")),
            ("conformance", include_str!("conformance.rs")),
            ("constitution", include_str!("constitution.rs")),
            ("controls", include_str!("controls.rs")),
            ("design", include_str!("design.rs")),
            (
                "design_materialization",
                include_str!("design_materialization.rs"),
            ),
            ("evidence", include_str!("evidence.rs")),
            ("executive", include_str!("executive.rs")),
            ("fleet", include_str!("fleet.rs")),
            ("knowledge", include_str!("knowledge.rs")),
            ("lifecycle", include_str!("lifecycle.rs")),
            ("waivers", include_str!("waivers.rs")),
            ("mod", include_str!("mod.rs")),
        ];

        let advertised: Vec<String> = list()
            .iter()
            .filter_map(|tool| tool["name"].as_str().map(str::to_string))
            .collect();

        let mut undeclared: Vec<String> = Vec::new();
        let mut dispatched = 0usize;

        for (module, source) in SOURCES {
            // Only the tool dispatch itself. Scanning whole files also matches
            // `"ratchet" => ControlKind::Ratchet` and friends, which are enum
            // parsing, not tools — a guard that reports those trains people to
            // ignore it.
            let mut from = 0usize;
            while let Some(at) = source[from..].find("match name {") {
                let start = from + at + "match name {".len();
                let end = source[start..]
                    .find("_ => None,")
                    .map(|e| start + e)
                    .unwrap_or(source.len());
                let block = &source[start..end];
                from = end;

                for (arm, _) in block.match_indices("\" => ") {
                    let before = &block[..arm];
                    let Some(open) = before.rfind('"') else {
                        continue;
                    };
                    let name = &before[open + 1..];
                    if name.is_empty() {
                        continue;
                    }
                    dispatched += 1;
                    if !advertised.iter().any(|a| a == name) {
                        undeclared.push(format!("{module}::{name}"));
                    }
                }
            }
        }

        // A source scan that matches nothing passes silently, which is the
        // failure this test exists to catch, one level up.
        assert!(
            dispatched >= 40,
            "the scan found only {dispatched} dispatch arms, so it is no longer \
             reading the dispatch it claims to guard"
        );

        undeclared.sort();
        undeclared.dedup();
        assert!(
            undeclared.is_empty(),
            "the server answers to these but advertises none of them:\n  {}",
            undeclared.join("\n  ")
        );
    }

    #[test]
    fn tool_contract_requires_evidence_and_exposes_binding_mode() {
        let tools = list();
        let complete = tools
            .iter()
            .find(|tool| tool["name"] == "complete_task")
            .unwrap();
        assert!(complete["inputSchema"]["required"]
            .as_array()
            .unwrap()
            .iter()
            .any(|value| value == "evidence"));
        let link = tools
            .iter()
            .find(|tool| tool["name"] == "link_goal_to_code")
            .unwrap();
        assert_eq!(
            link["inputSchema"]["properties"]["mode"]["default"],
            "governed"
        );
        let create = tools
            .iter()
            .find(|tool| tool["name"] == "create_task")
            .unwrap();
        assert!(create["inputSchema"]["properties"]["blocked_by"].is_object());
    }

    #[test]
    fn tools_list_exposes_no_duplicate_names() {
        // Regression: ADR-0022 copy-pasted the `consolidate` definition, so
        // tools/list advertised two identical entries and MCP clients saw an
        // ambiguous, duplicated verb. Every advertised tool name must be unique.
        let tools = list();
        let mut names: Vec<&str> = tools
            .iter()
            .map(|tool| tool["name"].as_str().unwrap())
            .collect();
        let total = names.len();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), total, "duplicate tool name in tools/list");

        for tool in tools.iter().filter(|tool| {
            tool["inputSchema"]["properties"]["session_id"].is_object()
                && tool["name"] != "open_session"
        }) {
            assert!(tool["inputSchema"]["properties"]["agent"].is_null());
            assert!(!tool["inputSchema"]["required"]
                .as_array()
                .unwrap()
                .iter()
                .any(|value| value == "agent"));
        }
    }

    /// A control registered under the wrong id used to be permanent: its
    /// version can never move backwards, so re-registering is refused, and
    /// `retire_control` lived on the facade without ever reaching the tool
    /// surface. Dead and duplicate mechanisms accumulated against live clauses
    /// and went on reporting.
    ///
    /// Driven through `bind_session` rather than by handing the tool an author,
    /// because that is the whole point: retiring a control weakens what its
    /// clause can enforce, so the author is resolved from the session and
    /// cannot be claimed.
    #[test]
    fn a_control_can_be_stood_down_through_the_tool_surface() {
        let engine = Lodestar::open_in_memory().unwrap();
        let sessions = SessionRegistry::new("copilot").unwrap();
        const TOKEN: &str = "00112233445566778899aabbccddeeff";
        let bound = |tool: &str, arguments: Value| -> Value {
            let params = json!({ "name": tool, "arguments": arguments });
            bind_session(&params, &sessions).expect("session binds")
        };

        call(
            &engine,
            &bound("open_session", json!({ "session_id": TOKEN })),
        )
        .expect("the session opens");

        let clause = engine
            .define_goal(
                lodestar_core::GoalKind::Constraint,
                "Modules stay small",
                "Split a module that outgrows its responsibility.",
                None,
            )
            .unwrap();

        let registered = call(
            &engine,
            &json!({
                "name": "register_control",
                "arguments": {
                    "control_id": "control:misnamed",
                    "clause_id": clause.id,
                    "kind": "check",
                    "power": "mechanical"
                }
            }),
        );
        assert!(registered.is_ok(), "the control registers: {registered:?}");

        let retired = call(
            &engine,
            &bound(
                "retire_control",
                json!({ "session_id": TOKEN, "control_id": "control:misnamed" }),
            ),
        )
        .expect("the control is stood down");
        let body: Value =
            serde_json::from_str(retired["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["status"], "retired");
        assert!(
            body["retired_by"].is_string(),
            "the stand-down names who did it: {body}"
        );

        // Retirement is not deletion: the control still records what it served,
        // which is why observations naming it resolve as unknown rather than
        // vanishing.
        let listed = call(
            &engine,
            &json!({
                "name": "clause_controls",
                "arguments": { "clause_id": clause.id }
            }),
        )
        .unwrap();
        let listed: Value =
            serde_json::from_str(listed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(listed["controls"][0]["status"], "retired");
    }

    /// Reporting success for a control that was never there would let a typo
    /// read as a completed stand-down.
    #[test]
    fn retiring_a_control_that_was_never_registered_is_refused() {
        let engine = Lodestar::open_in_memory().unwrap();
        let sessions = SessionRegistry::new("copilot").unwrap();
        const TOKEN: &str = "00112233445566778899aabbccddeeff";

        call(
            &engine,
            &bind_session(
                &json!({
                    "name": "open_session",
                    "arguments": { "session_id": TOKEN }
                }),
                &sessions,
            )
            .expect("session binds"),
        )
        .expect("the session opens");

        let params = bind_session(
            &json!({
                "name": "retire_control",
                "arguments": { "session_id": TOKEN, "control_id": "control:never-existed" }
            }),
            &sessions,
        )
        .expect("session binds");

        let error = call(&engine, &params).expect_err("an unknown control cannot be stood down");
        assert!(
            error.contains("control:never-existed"),
            "names the control it could not find: {error}"
        );
    }

    /// Without a session there is nobody to attribute the stand-down to, so the
    /// call must not quietly succeed unattributed.
    #[test]
    fn retiring_a_control_without_a_session_is_refused() {
        let sessions = SessionRegistry::new("copilot").unwrap();
        let error = bind_session(
            &json!({
                "name": "retire_control",
                "arguments": { "control_id": "control:misnamed" }
            }),
            &sessions,
        )
        .expect_err("an unbound stand-down is refused");
        assert!(
            error.contains("session_id"),
            "says a session is required: {error}"
        );
    }

    #[test]
    fn storage_status_returns_the_injected_startup_snapshot() {
        let engine = Lodestar::open_in_memory().unwrap();
        let status = StorageStatus {
            plane: "lodestar".into(),
            repository_id: Some("0123456789abcdef0123456789abcdef".into()),
            database_path: PathBuf::from("state/spec.db"),
            origin: DatabaseOrigin::Repository,
            legacy_path: Some(PathBuf::from("repo/.lodestar/spec.db")),
            migrated_legacy: false,
        };
        let params = json!({ "name": "storage_status", "arguments": {} });

        let result = call_with_storage(&engine, &params, Some(&status)).unwrap();
        let value: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(value["plane"], "lodestar");
        assert_eq!(value["repository_id"], status.repository_id.unwrap());
        assert_eq!(value["origin"], "repository");
        assert_eq!(value["migrated_legacy"], false);
    }
}
